-- Sprint 43 / V4.4. Additive and idempotent asset-management schema.
CREATE SCHEMA IF NOT EXISTS orcafacil;
CREATE TABLE IF NOT EXISTS orcafacil.asset_categories (id uuid PRIMARY KEY, account_id uuid NULL, name varchar(160) NOT NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_asset_categories_scope_name ON orcafacil.asset_categories(account_id,name) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS orcafacil.asset_models (id uuid PRIMARY KEY, account_id uuid NULL, category_id uuid NOT NULL, manufacturer varchar(160) NOT NULL, name varchar(160) NOT NULL, description text NULL, estimated_useful_life_months int NULL, suggested_maintenance_days int NULL, default_checklist_id uuid NULL, recommended_documents text NULL, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_asset_models_scope ON orcafacil.asset_models(account_id,category_id,manufacturer,name) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS orcafacil.customer_asset_locations (id uuid PRIMARY KEY, account_id uuid NOT NULL, client_id uuid NOT NULL, name varchar(160) NOT NULL, address text NOT NULL, sector varchar(160), room varchar(160), reference text, local_contact varchar(200), notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_asset_locations_tenant_client ON orcafacil.customer_asset_locations(account_id,client_id) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS orcafacil.customer_assets (id uuid PRIMARY KEY, account_id uuid NOT NULL, client_id uuid NOT NULL, category_id uuid NOT NULL, model_id uuid NULL, location_id uuid NULL, name varchar(200) NOT NULL, serial_number varchar(200), inventory_number varchar(200), manufacturer varchar(160), installed_on date, acquired_on date, status int NOT NULL DEFAULT 0, criticality int NOT NULL DEFAULT 1, notes text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_customer_assets_serial ON orcafacil.customer_assets(account_id,client_id,serial_number) WHERE is_deleted=false AND serial_number IS NOT NULL;
CREATE INDEX IF NOT EXISTS ix_customer_assets_tenant ON orcafacil.customer_assets(account_id,client_id,status) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS orcafacil.customer_asset_warranties (id uuid PRIMARY KEY, account_id uuid NOT NULL, asset_id uuid NOT NULL, type varchar(120) NOT NULL, supplier varchar(200), starts_on date NOT NULL, ends_on date NOT NULL, conditions text, document_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false, CONSTRAINT ck_asset_warranty_dates CHECK(ends_on>=starts_on));
CREATE TABLE IF NOT EXISTS orcafacil.maintenance_plans (id uuid PRIMARY KEY, account_id uuid NOT NULL, client_id uuid NOT NULL, contract_id uuid, name varchar(200) NOT NULL, frequency int NOT NULL, interval int NOT NULL DEFAULT 1, maintenance_type varchar(80) NOT NULL, checklist_id uuid, responsible_user_id uuid, is_active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.maintenance_plan_assets (id uuid PRIMARY KEY, account_id uuid NOT NULL, plan_id uuid NOT NULL, asset_id uuid NOT NULL, next_due_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_maintenance_plan_assets ON orcafacil.maintenance_plan_assets(account_id,plan_id,asset_id) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS orcafacil.maintenance_generated_work_orders (id uuid PRIMARY KEY, account_id uuid NOT NULL, plan_id uuid NOT NULL, asset_id uuid NOT NULL, work_order_id uuid, period_start date NOT NULL, period_end date NOT NULL, status varchar(40) NOT NULL, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_preventive_generation_period ON orcafacil.maintenance_generated_work_orders(account_id,plan_id,asset_id,period_start) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS orcafacil.inspection_templates (id uuid PRIMARY KEY, account_id uuid NULL, category_id uuid, model_id uuid, name varchar(200) NOT NULL, version int NOT NULL DEFAULT 1, is_published boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.inspection_template_items (id uuid PRIMARY KEY, account_id uuid NULL, template_id uuid NOT NULL, section varchar(160) NOT NULL, prompt text NOT NULL, answer_type varchar(40) NOT NULL, is_required boolean NOT NULL DEFAULT false, is_critical boolean NOT NULL DEFAULT false, display_order int NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.asset_inspections (id uuid PRIMARY KEY, account_id uuid NOT NULL, client_id uuid NOT NULL, asset_id uuid NOT NULL, template_id uuid NOT NULL, technician_user_id uuid NOT NULL, work_order_id uuid, status int NOT NULL DEFAULT 0, result text, rejection_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.asset_inspection_answers (id uuid PRIMARY KEY, account_id uuid NOT NULL, inspection_id uuid NOT NULL, template_item_id uuid NOT NULL, value text, is_non_conforming boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_inspection_answers ON orcafacil.asset_inspection_answers(inspection_id,template_item_id) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS orcafacil.non_conformities (id uuid PRIMARY KEY, account_id uuid NOT NULL, client_id uuid NOT NULL, asset_id uuid NOT NULL, inspection_id uuid, work_order_id uuid, description text NOT NULL, severity int NOT NULL, status int NOT NULL DEFAULT 0, responsible_user_id uuid, due_at timestamptz, cancellation_reason text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE INDEX IF NOT EXISTS ix_non_conformities_tenant_status ON orcafacil.non_conformities(account_id,status,severity) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS orcafacil.corrective_action_plans (id uuid PRIMARY KEY, account_id uuid NOT NULL, non_conformity_id uuid NOT NULL, responsible_user_id uuid NOT NULL, due_at timestamptz NOT NULL, status int NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.corrective_action_items (id uuid PRIMARY KEY, account_id uuid NOT NULL, plan_id uuid NOT NULL, description text NOT NULL, responsible_user_id uuid NOT NULL, due_at timestamptz NOT NULL, completed_at timestamptz, evidence_file_id uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS orcafacil.technical_reports (id uuid PRIMARY KEY, account_id uuid NOT NULL, client_id uuid NOT NULL, asset_id uuid NOT NULL, origin_type varchar(60) NOT NULL, origin_id uuid NOT NULL, technical_responsible_user_id uuid NOT NULL, conclusion text, recommendations text, status int NOT NULL, version int NOT NULL DEFAULT 1, published_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_technical_report_versions ON orcafacil.technical_reports(account_id,origin_type,origin_id,version) WHERE is_deleted=false;
CREATE TABLE IF NOT EXISTS orcafacil.asset_qr_codes (id uuid PRIMARY KEY, account_id uuid NOT NULL, asset_id uuid NOT NULL, token_hash varchar(64) NOT NULL, expires_at timestamptz, revoked_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
CREATE UNIQUE INDEX IF NOT EXISTS ux_asset_qr_token_hash ON orcafacil.asset_qr_codes(token_hash);
CREATE TABLE IF NOT EXISTS orcafacil.asset_qr_access_logs (id uuid PRIMARY KEY, account_id uuid NOT NULL, qr_code_id uuid NOT NULL, accessed_at timestamptz NOT NULL DEFAULT now(), ip_hash varchar(64), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false);
-- Supporting history/evidence tables remain additive and intentionally generic.
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['customer_asset_components','customer_asset_documents','customer_asset_contract_links','customer_asset_service_history','maintenance_plan_items','maintenance_plan_schedules','maintenance_plan_events','maintenance_preventive_rules','maintenance_corrective_events','inspection_template_sections','asset_inspection_evidences','asset_inspection_findings','non_conformity_events','corrective_action_evidences','quality_reviews','quality_review_items','technical_report_sections','technical_report_evidences','asset_health_scores','asset_replacement_recommendations','asset_failure_events','asset_downtime_events','asset_parts_usage','asset_lifecycle_events'] LOOP EXECUTE format('CREATE TABLE IF NOT EXISTS orcafacil.%I (id uuid PRIMARY KEY, account_id uuid NOT NULL, parent_id uuid, event_type varchar(80), payload_json jsonb NOT NULL DEFAULT ''{}''::jsonb, occurred_at timestamptz NOT NULL DEFAULT now(), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NULL, is_deleted boolean NOT NULL DEFAULT false)',t); EXECUTE format('CREATE INDEX IF NOT EXISTS %I ON orcafacil.%I(account_id,parent_id) WHERE is_deleted=false','ix_'||t||'_tenant_parent',t); END LOOP; END $$;
